define dimension Time; define unit Second: Time; type Bounded = int where self >= 1 and self <= 42; type Small = int where self >= 1 and self <= 21; type Duration = int where self >= 1 and self <= 42 and units in Second;
type NegativeSmall = int where self >= -21 and self <= -1;
fnc f(Small n) -> NegativeSmall { return -n; } pub fnc main() -> int { return f(1)+43; }
